window.ScripturaLexicons.LSJ.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1284\" data-lsj-orig-id=\"n1284\" data-lsj-ordinal=\"1301\"><td class=\"greek\">ἀδιάκριτος</td><td>LSJ</td><td>Indistinguível, misturado; não discriminado; comum, sem distinção; ininteligível; indeciso; que não distingue devidamente; sem exame prévio.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1285\" data-lsj-orig-id=\"n1285\" data-lsj-ordinal=\"1302\"><td class=\"greek\">ἀδιακωλύτως</td><td>LSJ</td><td>Sem impedimento, livremente, sem obstáculo (advérbio).</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1286\" data-lsj-orig-id=\"n1286\" data-lsj-ordinal=\"1303\"><td class=\"greek\">ἀδιάλειπτος</td><td>LSJ</td><td>Ininterrupto, incessante, contínuo; também uso adverbial.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1287\" data-lsj-orig-id=\"n1287\" data-lsj-ordinal=\"1304\"><td class=\"greek\">ἀδιάλεκτος</td><td>LSJ</td><td>Sem conversação, sem interlocução; de vida, solitária.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1288\" data-lsj-orig-id=\"n1288\" data-lsj-ordinal=\"1305\"><td class=\"greek\">ἀδιαληπτεύω</td><td>LSJ</td><td>Ter falta de compreensão; ficar confuso no pensamento.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1289\" data-lsj-orig-id=\"n1289\" data-lsj-ordinal=\"1306\"><td class=\"greek\">ἀδιάληπτος</td><td>LSJ</td><td>Indistinto, confuso, obscuro (de discurso); mentalmente confuso (de pessoa).</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1290\" data-lsj-orig-id=\"n1290\" data-lsj-ordinal=\"1307\"><td class=\"greek\">ἀδιαληψία</td><td>LSJ</td><td>Confusão, obscuridade de pensamentos; incapacidade de distinguir.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1291\" data-lsj-orig-id=\"n1291\" data-lsj-ordinal=\"1308\"><td class=\"greek\">ἀδιάλλακτος</td><td>LSJ</td><td>Irreconciliável; que não admite reconciliação.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1292\" data-lsj-orig-id=\"n1292\" data-lsj-ordinal=\"1309\"><td class=\"greek\">ἀδιαλόγιστος</td><td>LSJ</td><td>Sem ponderação ou raciocínio; irrefletido.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1293\" data-lsj-orig-id=\"n1293\" data-lsj-ordinal=\"1310\"><td class=\"greek\">ἀδιάλυτος</td><td>LSJ</td><td>Não dissolvido; indissolúvel; indestrutível; irreconciliável.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1294\" data-lsj-orig-id=\"n1294\" data-lsj-ordinal=\"1311\"><td class=\"greek\">ἀδιαλώβητον</td><td>LSJ</td><td>Inofensivo, não prejudicial: glosa grega equivalente a ἀβλαβές.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1295\" data-lsj-orig-id=\"n1295\" data-lsj-ordinal=\"1312\"><td class=\"greek\">ἀδιαμάρτητος</td><td>LSJ</td><td>Infalível, que não erra.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1296\" data-lsj-orig-id=\"n1296\" data-lsj-ordinal=\"1313\"><td class=\"greek\">ἀδιαμέριστος</td><td>LSJ</td><td>Indiviso, indivisível: equivalente a ἀδιαίρετος; ver o lema remetido.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1297\" data-lsj-orig-id=\"n1297\" data-lsj-ordinal=\"1314\"><td class=\"greek\">ἀδιαμόρφωτος</td><td>LSJ</td><td>Ainda não completamente formado; não modelado definitivamente.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1297a\" data-lsj-orig-id=\"n1297a\" data-lsj-ordinal=\"1315\"><td class=\"greek\">ἀδιανέμητος</td><td>LSJ</td><td>Que não deve ser dividido; não dividido, indiviso.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1298\" data-lsj-orig-id=\"n1298\" data-lsj-ordinal=\"1316\"><td class=\"greek\">ἀδιανοησία</td><td>LSJ</td><td>Inconcebibilidade; impossibilidade de conceber intelectualmente.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1299\" data-lsj-orig-id=\"n1299\" data-lsj-ordinal=\"1317\"><td class=\"greek\">ἀδιανοητεύομαι</td><td>LSJ</td><td>Falar de modo ininteligível.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1300\" data-lsj-orig-id=\"n1300\" data-lsj-ordinal=\"1318\"><td class=\"greek\">ἀδιανόητος</td><td>LSJ</td><td>Ininteligível; inconcebível; que não compreende, tolo; irrefletido.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1301\" data-lsj-orig-id=\"n1301\" data-lsj-ordinal=\"1319\"><td class=\"greek\">ἀδίαντος</td><td>LSJ</td><td>Não molhado, não umedecido; não banhado em suor; como nome botânico, avenca (Adiantum capillus-veneris).</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1302\" data-lsj-orig-id=\"n1302\" data-lsj-ordinal=\"1320\"><td class=\"greek\">ἀδιάξεστος</td><td>LSJ</td><td>Não polido, não alisado.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1303\" data-lsj-orig-id=\"n1303\" data-lsj-ordinal=\"1321\"><td class=\"greek\">ἀδιαπάτητος</td><td>LSJ</td><td>Não pisado, não percorrido.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1304\" data-lsj-orig-id=\"n1304\" data-lsj-ordinal=\"1322\"><td class=\"greek\">ἀδιάπαυστος</td><td>LSJ</td><td>Que não se pode acalmar; incessante, violento; forma adverbial atestada.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1305\" data-lsj-orig-id=\"n1305\" data-lsj-ordinal=\"1323\"><td class=\"greek\">ἀδιάπεπτος</td><td>LSJ</td><td>Não digerido; indigesto.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1306\" data-lsj-orig-id=\"n1306\" data-lsj-ordinal=\"1324\"><td class=\"greek\">ἀδιάπλαστος</td><td>LSJ</td><td>Ainda não formado ou modelado.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1307\" data-lsj-orig-id=\"n1307\" data-lsj-ordinal=\"1325\"><td class=\"greek\">ἀδιαπνευστέω</td><td>LSJ</td><td>Não evaporar, não exalar vapor.</td><td>LSJ</td></tr>";
